      new Set(["HTML", "CSS", "Markdown"]),
      new Set(["C", "Go", "Rust"])
    ];

    const form = document.getElementById("quiz-form");
    const result = document.getElementById("quiz-result");

    function selectedValues(name) {
      return [...form.querySelectorAll(`input[name="${name}"]:checked`)].map((input) => input.value);
    }

    function matchesExactly(selected, correct) {
      if (selected.length !== correct.size) {
        return false;
      }

      return selected.every((value) => correct.has(value));
    }

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const score = answers.reduce((total, correct, index) => {
        const selected = selectedValues(`q${index + 1}`);
        return total + (matchesExactly(selected, correct) ? 1 : 0);
      }, 0);

      result.textContent = `You got ${score} out of 3 correct.`;
    });
