         <h1 id="quiz-title">Computer Languages Quiz</h1>
         <p class="intro">Choose every answer that fits each question, then check your score.</p>
       </header>

       <form id="quiz-form" novalidate>
         <div class="form-field">
           <fieldset aria-describedby="q1-help">
             <legend>1. Which of these are general-purpose programming languages? <span class="required-marker" aria-hidden="true">*</span></legend>
             <p class="help-text" id="q1-help">Select all that apply.</p>
             <div class="options">
               <label class="option" for="q1-c">
                 <input id="q1-c" name="q1" type="checkbox" value="C">
                 <span>C</span>
               </label>
               <label class="option" for="q1-python">
                 <input id="q1-python" name="q1" type="checkbox" value="Python">
                 <span>Python</span>
               </label>
               <label class="option" for="q1-js">
                 <input id="q1-js" name="q1" type="checkbox" value="JavaScript">
                 <span>JavaScript</span>
               </label>
               <label class="option" for="q1-html">
                 <input id="q1-html" name="q1" type="checkbox" value="HTML">
                 <span>HTML</span>
               </label>
             </div>
           </fieldset>
         </div>

         <div class="form-field">
           <fieldset>
             <legend>2. Which of these are used to describe web content or presentation? <span class="required-marker" aria-hidden="true">*</span></legend>
             <div class="options">
               <label class="option" for="q2-html">
                 <input id="q2-html" name="q2" type="checkbox" value="HTML">
                 <span>HTML</span>
               </label>
               <label class="option" for="q2-css">
                 <input id="q2-css" name="q2" type="checkbox" value="CSS">
                 <span>CSS</span>
               </label>
               <label class="option" for="q2-md">
                 <input id="q2-md" name="q2" type="checkbox" value="Markdown">
                 <span>Markdown</span>
               </label>
               <label class="option" for="q2-sql">
                 <input id="q2-sql" name="q2" type="checkbox" value="SQL">
                 <span>SQL</span>
               </label>
             </div>
           </fieldset>
         </div>

         <div class="form-field">
           <fieldset>
             <legend>3. Which of these are typically compiled before running? <span class="required-marker" aria-hidden="true">*</span></legend>
             <div class="options">
               <label class="option" for="q3-c">
                 <input id="q3-c" name="q3" type="checkbox" value="C">
                 <span>C</span>
               </label>
               <label class="option" for="q3-go">
                 <input id="q3-go" name="q3" type="checkbox" value="Go">
                 <span>Go</span>
               </label>
               <label class="option" for="q3-rust">
                 <input id="q3-rust" name="q3" type="checkbox" value="Rust">
                 <span>Rust</span>
               </label>
               <label class="option" for="q3-node">
                 <input id="q3-node" name="q3" type="checkbox" value="JavaScript">
                 <span>JavaScript</span>
               </label>
             </div>
           </fieldset>
         </div>

         <div class="controls">
           <button type="submit">Check answers</button>
           <p class="result" id="quiz-result" role="status" aria-live="polite"></p>
         </div>
       </form>
     </section>
   </main>

   <script>
     const answers = [
       new Set(["C", "Python", "JavaScript"]),
       new Set(["HTML", "CSS", "Markdown"]),
       new Set(["C", "Go", "Rust"])
     ];

     const form = document.getElementById("quiz-form");
     const result = document.getElementById("quiz-result");

     function selectedValues(name) {
       return [...form.querySelectorAll(`input[name="${name}"]:checked`)].map((input) => input.value);
     }

     function matchesExactly(selected, correct) {
       if (selected.length !== correct.size) {
         return false;
       }

       return selected.every((value) => correct.has(value));
     }

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const score = answers.reduce((total, correct, index) => {
         const selected = selectedValues(`q${index + 1}`);
         return total + (matchesExactly(selected, correct) ? 1 : 0);
       }, 0);

       result.textContent = `You got ${score} out of 3 correct.`;
     });
